import { describe, expect, it } from "vitest";

import { classes, courses } from "../src/data";
import { getCourseOfferingHistory } from "../src/offeringHistory";

describe("getCourseOfferingHistory", () => {
  it("returns all classes for a never-renumbered course, skipping the gap term", () => {
    const history = getCourseOfferingHistory("crs-cs61a", courses, classes);

    expect(history.map((h) => h.class.classId)).toEqual([
      "cls-61a-f23",
      "cls-61a-f24-1",
      "cls-61a-f24-2",
    ]);
  });

  it("includes multiple independent lecture sequences offered in the same term", () => {
    const history = getCourseOfferingHistory("crs-cs61a", courses, classes);
    const fall2024 = history.filter((h) => h.class.termId === "2024-Fall");

    expect(fall2024).toHaveLength(2);
    expect(fall2024.map((h) => h.class.number).sort()).toEqual(["001", "002"]);
  });

  it("marks a never-renumbered course's offerings as under its current identity", () => {
    const history = getCourseOfferingHistory("crs-cs61a", courses, classes);
    expect(history.every((h) => h.offeredUnderPriorIdentity === false)).toBe(
      true
    );
  });

  it("includes classes offered BEFORE a renumbering, joined by courseId", () => {
    const history = getCourseOfferingHistory("crs-econ1", courses, classes);

    expect(history.map((h) => h.class.classId)).toEqual([
      "cls-econ-f22",
      "cls-econ-s23",
      "cls-econ-f23",
    ]);
  });

  it("flags pre-renumbering offerings and not post-renumbering ones", () => {
    const history = getCourseOfferingHistory("crs-econ1", courses, classes);
    const byId = Object.fromEntries(
      history.map((h) => [h.class.classId, h.offeredUnderPriorIdentity])
    );

    expect(byId["cls-econ-f22"]).toBe(true);
    expect(byId["cls-econ-s23"]).toBe(true);
    expect(byId["cls-econ-f23"]).toBe(false);
  });

  it("preserves each offering's own subject/number as of its own term", () => {
    const history = getCourseOfferingHistory("crs-econ1", courses, classes);
    const f22 = history.find((h) => h.class.classId === "cls-econ-f22")!;
    const f23 = history.find((h) => h.class.classId === "cls-econ-f23")!;

    expect(f22.class.subject).toBe("ECON");
    expect(f22.class.courseNumber).toBe("1");
    expect(f23.class.courseNumber).toBe("101A");
  });

  it("returns an empty array for a course that has never had a class", () => {
    const history = getCourseOfferingHistory("crs-ling142", courses, classes);
    expect(history).toEqual([]);
  });

  it("returns an empty array for an unknown courseId", () => {
    const history = getCourseOfferingHistory("crs-does-not-exist", courses, classes);
    expect(history).toEqual([]);
  });
});
